The edit was successful with no linter errors."},{"role":"assistant","content":[{"type":"text","text":"Now let's create the Network Connectivity Monitor:"}],"tool_calls":[{"id":"toolu_bdrk_01JS7jRpAMjHwLZDBjf823nw","type":"function","function":{"name":"edit_file","arguments":"{"target_file": "app/src/main/java/kv/apps/taskmanager/data/connectivity/NetworkConnectivityObserver.kt", "instructions": "I'll create a network connectivity observer to monitor online/offline state", "code_edit": "package kv.apps.taskmanager.data.connectivity\n\nimport android.content.Context\nimport android.net.ConnectivityManager\nimport android.net.Network\nimport android.net.NetworkCapabilities\nimport android.net.NetworkRequest\nimport kotlinx.coroutines.channels.awaitClose\nimport kotlinx.coroutines.flow.Flow\nimport kotlinx.coroutines.flow.callbackFlow\nimport kotlinx.coroutines.flow.distinctUntilChanged\nimport javax.inject.Inject\nimport javax.inject.Singleton\n\ninterface ConnectivityObserver {\n fun observe(): Flow<NetworkStatus>\n fun isOnline(): Boolean\n}\n\nenum class NetworkStatus {\n AVAILABLE, UNAVAILABLE, LOSING, LOST\n}\n\n@Singleton\nclass NetworkConnectivityObserver @Inject constructor(\n private val context: Context\n) : ConnectivityObserver {\n\n private val connectivityManager =\n context.getSystemService(Context.CONNECTIVITY_SERVICE) as ConnectivityManager\n\n override fun observe(): Flow<NetworkStatus> {\n return callbackFlow {\n val callback = object : ConnectivityManager.NetworkCallback() {\n override fun onAvailable(network: Network) {\n super.onAvailable(network)\n trySend(NetworkStatus.AVAILABLE)\n }\n\n override fun onLosing(network: Network, maxMsToLive: Int) {\n super.onLosing(network, maxMsToLive)\n trySend(NetworkStatus.LOSING)\n }\n\n override fun onLost(network: Network) {\n super.onLost(network)\n trySend(NetworkStatus.LOST)\n }\n\n override fun onUnavailable() {\n super.onUnavailable()\n trySend(NetworkStatus.UNAVAILABLE)\n }\n }\n\n val request = NetworkRequest.Builder()\n .addCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)\n .addTransportType(NetworkCapabilities.TRANSPORT_WIFI)\n .addTransportType(NetworkCapabilities.TRANSPORT_CELLULAR)\n .build()\n\n connectivityManager.registerNetworkCallback(request, callback)\n\n // Send current state\n trySend(\n if (isOnline()) NetworkStatus.AVAILABLE \n else NetworkStatus.UNAVAILABLE\n )\n\n awaitClose {\n connectivityManager.unregisterNetworkCallback(callback)\n }\n }.distinctUntilChanged()\n }\n\n override fun isOnline(): Boolean {\n val activeNetwork = connectivityManager.activeNetwork ?: return false\n val capabilities = connectivityManager.getNetworkCapabilities(activeNetwork) ?: return false\n return capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET) &&\n capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)\n }\n}"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_01JS7jRpAMjHwLZDBjf823nw","content":"The apply model made the following changes to the file:

```
@@ -1,1 +1,82 @@
+package kv.apps.taskmanager.data.connectivity

+import android.content.Context
+import android.net.ConnectivityManager
+import android.net.Network
+import android.net.NetworkCapabilities
+import android.net.NetworkRequest
+import kotlinx.coroutines.channels.awaitClose
+import kotlinx.coroutines.flow.Flow
+import kotlinx.coroutines.flow.callbackFlow
+import kotlinx.coroutines.flow.distinctUntilChanged
+import javax.inject.Inject
+import javax.inject.Singleton
+
+interface ConnectivityObserver {
+ fun observe(): Flow<NetworkStatus>
+ fun isOnline(): Boolean
+}
+
+enum class NetworkStatus {
+ AVAILABLE, UNAVAILABLE, LOSING, LOST
+}
+
+@Singleton
+class NetworkConnectivityObserver @Inject constructor(
+ private val context: Context
+) : ConnectivityObserver {
+
+ private val connectivityManager =
+ context.getSystemService(Context.CONNECTIVITY_SERVICE) as ConnectivityManager
+
+ override fun observe(): Flow<NetworkStatus> {
+ return callbackFlow {
+ val callback = object : ConnectivityManager.NetworkCallback() {
+ override fun onAvailable(network: Network) {
+ super.onAvailable(network)
+ trySend(NetworkStatus.AVAILABLE)
+ }
+
+ override fun onLosing(network: Network, maxMsToLive: Int) {
+ super.onLosing(network, maxMsToLive)
+ trySend(NetworkStatus.LOSING)
+ }
+
+ override fun onLost(network: Network) {
+ super.onLost(network)
+ trySend(NetworkStatus.LOST)
+ }
+
+ override fun onUnavailable() {
+ super.onUnavailable()
+ trySend(NetworkStatus.UNAVAILABLE)
+ }
+ }
+
+ val request = NetworkRequest.Builder()
+ .addCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)
+ .addTransportType(NetworkCapabilities.TRANSPORT_WIFI)
+ .addTransportType(NetworkCapabilities.TRANSPORT_CELLULAR)
+ .build()
+
+ connectivityManager.registerNetworkCallback(request, callback)
+
+ // Send current state
+ trySend(
+ if (isOnline()) NetworkStatus.AVAILABLE
+ else NetworkStatus.UNAVAILABLE
+ )
+
+ awaitClose {
+ connectivityManager.unregisterNetworkCallback(callback)
+ }
+ }.distinctUntilChanged()
+ }
+
+ override fun isOnline(): Boolean {
+ val activeNetwork = connectivityManager.activeNetwork ?: return false
+ val capabilities = connectivityManager.getNetworkCapabilities(activeNetwork) ?: return false
+ return capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET) &&
+ capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)
+ }
+}
```

