+ if (remoteTask != null) {
+ taskDao.insertTask(remoteTask.toEntity())
+ }
+ } catch (e: Exception) {
+ // Continue with local data if remote fails
+ }
+ }
+
+ // Return local data
+ return taskDao.getTaskById(taskId)?.toDomain()
